const max_text:usize=4096;
export fn prefix_function(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{if(v==null or n<1 or n>max_text+1 or v[0]<0 or v[0]>max_text)return -1;const len:usize=@intCast(v[0]);if(n!=len+1)return -1;for(0..len)|i|{if(v[i+1]<0 or v[i+1]>127)return -1;}const bytes=4*len;if(bytes>cap or(out==null and bytes>0))return -2;var pi=[_]usize{0}**max_text;for(1..len)|i|{var j=pi[i-1];while(j>0 and v[i+1]!=v[j+1]){j=pi[j-1];}if(v[i+1]==v[j+1])j+=1;pi[i]=j;}for(0..len)|i|{const x: u32=@intCast(pi[i]);for(0..4)|k|{out[4*i+k]=@truncate(x>>(8*k));}}return @intCast(bytes);}
